// Downloads over HTTPS with libcurl (download.h)

#include "download.h"

#include <QDir>
#include <QFile>
#include <QUrl>

#include <curl/curl.h>
#ifdef XP_CURL_DLOPEN
#include <dlfcn.h>
#endif

#include "log.h"
#include "version.h"		// generated by CMake

namespace {

// libcurl's calls, taken from the library loaded at run time on Linux, else linked
struct dlApi {
	CURLcode (*global_init)(long) = nullptr;
	CURL* (*easy_init)(void) = nullptr;
	CURLcode (*easy_setopt)(CURL*, CURLoption, ...) = nullptr;
	CURLcode (*easy_perform)(CURL*) = nullptr;
	CURLcode (*easy_getinfo)(CURL*, CURLINFO, ...) = nullptr;
	void (*easy_cleanup)(CURL*) = nullptr;
	const char* (*easy_strerror)(CURLcode) = nullptr;
	curl_version_info_data* (*version_info)(CURLversion) = nullptr;
	bool ok = false;
	QString why;
};

#ifdef XP_CURL_DLOPEN
template <typename T> bool dl_sym(void* lib, const char* name, T* fn) {
	*fn = reinterpret_cast<T>(dlsym(lib, name));
	return *fn != nullptr;
}
#endif

// Loaded and set up once, by the first caller: the GUI thread, before any worker
// starts, since curl_global_init is not thread-safe in older libcurl
const dlApi& dl_api() {
	static dlApi api;
	static std::once_flag once;
	std::call_once(once, []() {
#ifdef XP_CURL_DLOPEN
		void* lib = nullptr;
		// the same ABI either way; Debian may have only the GnuTLS one
		for (const char* name : {"libcurl.so.4", "libcurl-gnutls.so.4"}) {
			lib = dlopen(name, RTLD_NOW | RTLD_LOCAL);
			if (lib) break;
		}
		if (!lib) {
			api.why = "Downloading needs libcurl: install the libcurl4 or libcurl package";
			return;
		}
		bool all = dl_sym(lib, "curl_global_init", &api.global_init)
			&& dl_sym(lib, "curl_easy_init", &api.easy_init)
			&& dl_sym(lib, "curl_easy_setopt", &api.easy_setopt)
			&& dl_sym(lib, "curl_easy_perform", &api.easy_perform)
			&& dl_sym(lib, "curl_easy_getinfo", &api.easy_getinfo)
			&& dl_sym(lib, "curl_easy_cleanup", &api.easy_cleanup)
			&& dl_sym(lib, "curl_easy_strerror", &api.easy_strerror)
			&& dl_sym(lib, "curl_version_info", &api.version_info);
		if (!all) {
			api.why = "The libcurl here lacks what downloading needs";
			return;
		}
#else
		api.global_init = curl_global_init;
		api.easy_init = curl_easy_init;
		api.easy_setopt = curl_easy_setopt;
		api.easy_perform = curl_easy_perform;
		api.easy_getinfo = curl_easy_getinfo;
		api.easy_cleanup = curl_easy_cleanup;
		api.easy_strerror = curl_easy_strerror;
		api.version_info = curl_version_info;
#endif
		if (api.global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) {
			api.why = "libcurl does not start";
			return;
		}
		curl_version_info_data* ver = api.version_info(CURLVERSION_NOW);
		xlog(XLG_NET, XLL_INFO, "download: libcurl %s, %s", ver->version, ver->ssl_version ? ver->ssl_version : "no TLS");
		api.ok = true;
	});
	return api;
}

// HTTPS only, redirects too
void dl_https_only(const dlApi& api, CURL* h) {
#if LIBCURL_VERSION_NUM >= 0x075500
	if (api.easy_setopt(h, CURLOPT_PROTOCOLS_STR, "https") == CURLE_OK) {
		api.easy_setopt(h, CURLOPT_REDIR_PROTOCOLS_STR, "https");
		return;
	}
#endif
	// a libcurl before 7.85 has only the bitmask: by number, as newer headers deprecate
	// the names (CURLOPT_PROTOCOLS, CURLOPT_REDIR_PROTOCOLS; 2 is CURLPROTO_HTTPS)
	api.easy_setopt(h, (CURLoption)(CURLOPTTYPE_LONG + 181), 2L);
	api.easy_setopt(h, (CURLoption)(CURLOPTTYPE_LONG + 182), 2L);
}

QString dl_error(const dlApi& api, CURLcode res, long code, const QString& host, const QString& writeErr, const char* detail) {
	switch (res) {
		case CURLE_COULDNT_RESOLVE_HOST:
		case CURLE_COULDNT_RESOLVE_PROXY:
		case CURLE_COULDNT_CONNECT:
			return QString("No connection to %0").arg(host);
		case CURLE_OPERATION_TIMEDOUT:
			return QString("%0 did not answer in time").arg(host);
		case CURLE_HTTP_RETURNED_ERROR:
			if (code == 404) return QString("%0 has no such file (404)").arg(host);
			return QString("%0 answered with error %1").arg(host).arg(code);
		case CURLE_WRITE_ERROR:
			return writeErr.isEmpty() ? QString("The download could not be written") : writeErr;
		case CURLE_PEER_FAILED_VERIFICATION:
			return QString("The certificate of %0 is not trusted here").arg(host);
		case CURLE_SSL_CONNECT_ERROR:
			return QString("No secure connection to %0: %1").arg(host).arg(*detail ? detail : api.easy_strerror(res));
		case CURLE_PARTIAL_FILE:
		case CURLE_RECV_ERROR:
		case CURLE_SEND_ERROR:
		case CURLE_GOT_NOTHING:
			return QString("The connection to %0 broke off").arg(host);
		case CURLE_UNSUPPORTED_PROTOCOL:
			return QString("%0 sent the download to an address that is not HTTPS").arg(host);
		default:
			return QString("%0: %1").arg(host).arg(api.easy_strerror(res));
	}
}

}	// namespace

// what one request needs in libcurl's callbacks
struct dlTransfer {
	xDownload* owner;
	const dlApi* api;
	CURL* h = nullptr;
	QFile* file = nullptr;		// toFile
	QByteArray* mem = nullptr;	// toMemory
	qint64 limit = 0;
	qint64 offset = 0;		// what the part held when the rest was asked for
	bool answered = false;		// the first chunk has come: the response code is known
	bool body = true;		// a 2xx: its body is the download
	qint64 whole = -1;		// the file's size by Content-Range, when it says
	QString writeErr;

	// "Content-Range: bytes 100-199/1000" or, refusing a range, "bytes */1000"
	static size_t header(char* data, size_t size, size_t count, void* user) {
		dlTransfer* t = static_cast<dlTransfer*>(user);
		const size_t len = size * count;
		QByteArray line = QByteArray(data, (int)len).trimmed();
		if (line.toLower().startsWith("content-range:")) {
			int at = line.lastIndexOf('/');
			bool ok = false;
			qint64 n = (at < 0) ? 0 : line.mid(at + 1).toLongLong(&ok);
			if (ok) t->whole = n;
		}
		return len;
	}

	static size_t write(char* data, size_t size, size_t count, void* user) {
		dlTransfer* t = static_cast<dlTransfer*>(user);
		const size_t len = size * count;
		if (t->owner->stop) return 0;
		if (!t->answered) {
			t->answered = true;
			long code = 0;
			t->api->easy_getinfo(t->h, CURLINFO_RESPONSE_CODE, &code);
			t->body = (code >= 200) && (code < 300);
			// asked for the rest and sent the whole: it starts over
			if (t->file && t->offset && (code != 206)) {
				t->offset = 0;
				if (!t->file->resize(0) || !t->file->seek(0)) {
					t->writeErr = "Cannot write " + QDir::toNativeSeparators(t->file->fileName());
					return 0;
				}
			}
		}
		if (!t->body) return len;	// an error page: libcurl reports the code
		if (t->file) {
			if (t->file->write(data, (qint64)len) != (qint64)len) {
				t->writeErr = QString("Cannot write %0: %1").arg(QDir::toNativeSeparators(t->file->fileName()), t->file->errorString());
				return 0;
			}
		} else {
			if (t->mem->size() + (qint64)len > t->limit) {
				t->writeErr = "The server sent more than expected";
				return 0;
			}
			t->mem->append(data, (int)len);
		}
		return len;
	}

	static int info(void* user, curl_off_t dltotal, curl_off_t dlnow, curl_off_t, curl_off_t) {
		dlTransfer* t = static_cast<dlTransfer*>(user);
		if (t->owner->stop) return 1;		// aborts the transfer
		// before the first chunk the total may be the whole file's or the rest's
		if (!t->answered) {
			t->owner->progress(t->offset, 0);
		} else {
			t->owner->progress(t->offset + dlnow, dltotal ? t->offset + dltotal : 0);
		}
		return 0;
	}
};

xDownload::~xDownload() {
	stop = true;
	if (worker.joinable()) worker.join();
}

void xDownload::toMemory(const QString& url, int timeout, qint64 limit) {
	start(url, QString(), timeout, limit);
}

void xDownload::toFile(const QString& url, const QString& part) {
	start(url, part, 0, 0);
}

void xDownload::cancel() {
	stop = true;
}

dlStatus xDownload::status() const {
	std::lock_guard<std::mutex> grd(lock);
	return st;
}

QByteArray xDownload::data() const {
	std::lock_guard<std::mutex> grd(lock);
	return mem;
}

void xDownload::progress(qint64 done, qint64 total) {
	std::lock_guard<std::mutex> grd(lock);
	st.done = done;
	st.total = total;
}

void xDownload::finish(int state, const QString& error) {
	std::lock_guard<std::mutex> grd(lock);
	st.state = state;
	st.error = error;
}

void xDownload::start(const QString& url, const QString& part, int timeout, qint64 limit) {
	stop = true;
	if (worker.joinable()) worker.join();
	stop = false;
	{
		std::lock_guard<std::mutex> grd(lock);
		st = dlStatus();
		st.state = DL_RUN;
		mem.clear();
	}
	QString why;
	if (!dl_available(&why)) {
		finish(DL_FAIL, why);
		return;
	}
	worker = std::thread(&xDownload::run, this, url, part, timeout, limit);
}

void xDownload::run(QString url, QString part, int timeout, qint64 limit) {
	const dlApi& api = dl_api();
	const QString host = QUrl(url).host();
	const QByteArray url8 = url.toUtf8();
	QFile file(part);
	QByteArray buf;
	if (!part.isEmpty() && !file.open(QIODevice::ReadWrite)) {
		finish(DL_FAIL, QString("Cannot write %0: %1").arg(QDir::toNativeSeparators(part), file.errorString()));
		return;
	}
	// a second go only after the server refused to continue the part
	for (int attempt = 0; attempt < 2; attempt++) {
		dlTransfer t;
		t.owner = this;
		t.api = &api;
		t.limit = limit;
		if (file.isOpen()) {
			t.file = &file;
			t.offset = file.size();
			file.seek(t.offset);
		} else {
			buf.clear();
			t.mem = &buf;
		}
		t.h = api.easy_init();
		if (!t.h) {
			finish(DL_FAIL, "libcurl does not start");
			return;
		}
		char detail[CURL_ERROR_SIZE] = {0};
		CURL* h = t.h;
		api.easy_setopt(h, CURLOPT_URL, url8.constData());
		dl_https_only(api, h);
		api.easy_setopt(h, CURLOPT_FOLLOWLOCATION, 1L);
		api.easy_setopt(h, CURLOPT_MAXREDIRS, 10L);
		api.easy_setopt(h, CURLOPT_NOSIGNAL, 1L);
		api.easy_setopt(h, CURLOPT_FAILONERROR, 1L);
		api.easy_setopt(h, CURLOPT_USERAGENT, XPRODUCT "/" XVERSION);
		api.easy_setopt(h, CURLOPT_ERRORBUFFER, detail);
		api.easy_setopt(h, CURLOPT_CONNECTTIMEOUT, 20L);
		// a stall: under a byte a second for half a minute
		api.easy_setopt(h, CURLOPT_LOW_SPEED_LIMIT, 1L);
		api.easy_setopt(h, CURLOPT_LOW_SPEED_TIME, 30L);
		if (timeout > 0) api.easy_setopt(h, CURLOPT_TIMEOUT, (long)timeout);
#ifdef _WIN32
		// an OCSP or CRL server out of reach (a proxy, a closed network) is not a failure
		api.easy_setopt(h, CURLOPT_SSL_OPTIONS, (long)CURLSSLOPT_REVOKE_BEST_EFFORT);
#endif
		api.easy_setopt(h, CURLOPT_WRITEFUNCTION, &dlTransfer::write);
		api.easy_setopt(h, CURLOPT_WRITEDATA, &t);
		api.easy_setopt(h, CURLOPT_HEADERFUNCTION, &dlTransfer::header);
		api.easy_setopt(h, CURLOPT_HEADERDATA, &t);
		api.easy_setopt(h, CURLOPT_NOPROGRESS, 0L);
		api.easy_setopt(h, CURLOPT_XFERINFOFUNCTION, &dlTransfer::info);
		api.easy_setopt(h, CURLOPT_XFERINFODATA, &t);
		if (t.offset > 0) api.easy_setopt(h, CURLOPT_RESUME_FROM_LARGE, (curl_off_t)t.offset);
		xlog(XLG_NET, XLL_INFO, "download: %s%s", url8.constData(),
			t.offset ? qPrintable(QString(" from byte %0").arg(t.offset)) : "");
		CURLcode res = api.easy_perform(h);
		long code = 0;
		api.easy_getinfo(h, CURLINFO_RESPONSE_CODE, &code);
		api.easy_cleanup(h);
		xlog(XLG_NET, XLL_INFO, "download: %s, HTTP %ld, %s%s%s", host.toUtf8().constData(), code,
			api.easy_strerror(res), *detail ? ": " : "", detail);
		if (stop) {
			finish(DL_CANCEL, QString());
			return;
		}
		// nothing past the end of the part: whole already, if the file is as long as it
		const bool refused = (res == CURLE_RANGE_ERROR) || (code == 416);
		if ((code == 416) && file.isOpen() && (t.offset > 0) && (t.whole == t.offset)) {
			res = CURLE_OK;
		} else if (refused && file.isOpen() && (t.offset > 0) && (attempt == 0)) {
			// no ranges here, or the file is not the one the part was of: anew
			if (!file.resize(0)) break;
			continue;
		} else if (code == 416) {
			res = CURLE_HTTP_RETURNED_ERROR;
		}
		if (res != CURLE_OK) {
			finish(DL_FAIL, dl_error(api, res, code, host, t.writeErr, detail));
			return;
		}
		if (file.isOpen()) {
			const qint64 size = file.size();
			if (!file.flush()) {
				finish(DL_FAIL, QString("Cannot write %0: %1").arg(QDir::toNativeSeparators(part), file.errorString()));
				return;
			}
			file.close();
			progress(size, size);
		} else {
			std::lock_guard<std::mutex> grd(lock);
			mem = buf;
			st.done = st.total = buf.size();
		}
		finish(DL_DONE, QString());
		return;
	}
	finish(DL_FAIL, QString("Cannot write %0").arg(QDir::toNativeSeparators(part)));
}

bool dl_available(QString* why) {
	const dlApi& api = dl_api();
	if (why) *why = api.why;
	return api.ok;
}
